text(await tools.exec_command({cmd:"cat > /app/output/sweep.py <<'PY'
from gen import *
def sweep(endbase,endarm,steps,tag):
    n=now(); sb=n[:3].copy();sp=pose(n[6:13])[0];R=np.load(OUT+'/toolR.npy');q=n[6:13]
    lo=np.array([-100,-2.239,-100,-2.569,-100,-2.089,-100]);hi=-lo
    for k in range(1,steps+1):
        t=k/steps;b=sb*(1-t)+np.array(endbase)*t;p=sp*(1-t)+np.array(endarm)*t
        def err(qx):
            pp,rr=pose(qx);return np.r_[(pp-p)*4,Rotation.from_matrix(R@rr.T).as_rotvec(),.008*(qx-q)]
        q=least_squares(err,np.clip(q,lo,hi),bounds=(lo,hi),max_nfev=80).x
        db=b-n[:3];dq=q-n[6:13]
        a=np.r_[np.clip(db,-.085,.085),np.clip(dq*2.5,-.095,.095),1]
        o=act(a,tag,False);n=np.array(o.meta['proprio']['now'])
        if k%10==0:print('sweep',k,'step',o.meta['control_steps'],'base',np.round(n[:3],3),'ee',np.round(pose(n[6:13])[0],3),'grip',round(n[20],3))
    return observe(tag)
if __name__=='__main__':sweep([1.78,.125,-np.pi],[.55,.205,.299],24,'half_sweep')
PY
